  '.claude-plugin/marketplace.json':
    '{\n  "name": "merv",\n  "owner": {\n    "name": "RapidReview"\n  },\n  "metadata": {\n    "description": "Merv\'s client plugin for Claude Code."\n  },\n  "plugins": [\n    {\n      "name": "merv",\n      "source": "./claude-code",\n      "version": "0.5.2"\n    }\n  ]\n}\n',
  'claude-code/.claude-plugin/plugin.json':
    '{\n  "name": "merv",\n  "version": "0.5.2",\n  "description": "Use Merv for research projects: experiments, tasks, papers, artifacts, reviews and status through remote MCP with browser sign-in.",\n  "author": {\n    "name": "RapidReview"\n  },\n  "keywords": ["research", "ml", "mcp", "experiments"]\n}\n',
